        assert!(snap.text_chunks[0].compressed);
        assert_eq!(snap.text_chunks[1].keyword, "Title");
        assert_eq!(snap.text_chunks[1].value, "valeur");
        assert_eq!(snap.text_chunks[1].kind, PngTextKind::IText);
