syntax = "proto3";
package semio.s_stdio_png.snapshot;

// 🎨️ PNG §11.2.2 IHDR color type. PALETTE requires a PLTE chunk.
enum PngColorType {
  PNG_COLOR_TYPE_GRAYSCALE = 0;
  PNG_COLOR_TYPE_RGB = 1;
  PNG_COLOR_TYPE_PALETTE = 2;
  PNG_COLOR_TYPE_GRAYSCALE_ALPHA = 3;
  PNG_COLOR_TYPE_RGBA = 4;
}

// 🎨️ One PLTE entry — a weak value (whole-value replaced in diffs).
message PngRgb {
  uint32 r = 1;
  uint32 g = 2;
  uint32 b = 3;
}

// 👁️ Typed tRNS payload — shape depends on color_type (§11.3.3).
message PngTransparency {
  oneof value {
    IndexedAlpha indexed = 1;
    GrayAlpha grayscale = 2;
    RgbAlpha rgb = 3;
  }
  message IndexedAlpha { bytes alpha = 1; }
  message GrayAlpha { uint32 gray = 1; }
  message RgbAlpha { uint32 r = 1; uint32 g = 2; uint32 b = 3; }
}

// 📐️ cHRM — CIE xy chromaticity coordinates, each value * 100000 (§11.3.5.2).
message PngChromaticities {
  uint32 white_x = 1;
  uint32 white_y = 2;
  uint32 red_x = 3;
  uint32 red_y = 4;
  uint32 green_x = 5;
  uint32 green_y = 6;
  uint32 blue_x = 7;
  uint32 blue_y = 8;
}

// 🖌️ sRGB rendering intent (§11.3.5.3).
enum PngSrgbIntent {
  PNG_SRGB_INTENT_PERCEPTUAL = 0;
  PNG_SRGB_INTENT_RELATIVE_COLORIMETRIC = 1;
  PNG_SRGB_INTENT_SATURATION = 2;
  PNG_SRGB_INTENT_ABSOLUTE_COLORIMETRIC = 3;
}

// 📏️ pHYs — pixel-per-unit density (§11.3.5.4).
message PngPhysicalDims {
  uint32 ppu_x = 1;
  uint32 ppu_y = 2;
  bool unit_is_meter = 3;
}

// 🕰️ tIME — last modification time, UTC (§11.3.6.1).
message PngTimestamp {
  uint32 year = 1;
  uint32 month = 2;
  uint32 day = 3;
  uint32 hour = 4;
  uint32 minute = 5;
  uint32 second = 6;
}

// 🖼️ bKGD — default background color; shape depends on color_type (§11.3.5.1).
message PngBackground {
  oneof value {
    GrayBg grayscale = 1;
    RgbBg rgb = 2;
    IndexedBg indexed = 3;
  }
  message GrayBg { uint32 gray = 1; }
  message RgbBg { uint32 r = 1; uint32 g = 2; uint32 b = 3; }
  message IndexedBg { uint32 index = 1; }
}

// 🔤 Which of tEXt/zTXt/iTXt (§11.3.4) a PngTextChunk came from.
enum PngTextKind {
  PNG_TEXT_KIND_TEXT = 0;
  PNG_TEXT_KIND_Z_TEXT = 1;
  PNG_TEXT_KIND_I_TEXT = 2;
}

// 💬️ One tEXt/zTXt/iTXt chunk. Index-keyed within PngSnapshot.text_chunks.
message PngTextChunk {
  string keyword = 1;
  string value = 2;
  bool compressed = 3;
  PngTextKind kind = 4;
  string language_tag = 5;
  string translated_keyword = 6;
}

// 🗃️ A chunk the codec doesn't specifically model, retained verbatim.
message PngChunk {
  bytes kind = 1; // always 4 bytes
  bytes data = 2;
}

// 🧭️ One slot in the file's real chunk sequence.
message PngChunkMarker {
  enum Kind {
    IHDR = 0; PLTE = 1; TRNS = 2; GAMA = 3; CHRM = 4; SRGB = 5; PHYS = 6;
    TIME = 7; BKGD = 8; IDAT = 9; IEND = 10; TEXT = 11; UNKNOWN = 12;
  }
  Kind chunk = 1;
  optional uint64 index = 2; // set for TEXT/UNKNOWN
}

// 📸️ Complete stdio.png 1.2 semantic snapshot. schema is an identity field, never diffed.
message PngSnapshot {
  string schema = 1;
  uint32 width = 2;
  uint32 height = 3;
  uint32 bit_depth = 4;
  PngColorType color_type = 5;
  bool interlace = 6;
  repeated PngRgb plte = 7;
  optional PngTransparency trns = 8;
  optional uint32 gama = 9;
  optional PngChromaticities chrm = 10;
  optional PngSrgbIntent srgb = 11;
  optional PngPhysicalDims phys = 12;
  optional PngTimestamp time = 13;
  optional PngBackground bkgd = 14;
  repeated PngTextChunk text_chunks = 15;
  bytes pixels = 16;
  repeated PngChunkMarker chunk_order = 17;
  repeated PngChunk unknown_chunks = 18;
}

/** 🧬️ PngSnapshot schema facet — mirrors 🦀️component.rs field-for-field. Complete PNG 1.2
 * semantic model: typed IHDR/PLTE/tRNS, the full typed ancillary set, index-keyed text chunks,
 * decoded pixels, and chunk-order + unknown-chunk verbatim retention. */

/** 🎨️ PNG §11.2.2 IHDR color type. `Palette` requires a `PLTE` chunk. */
export type PngColorType = 'grayscale' | 'rgb' | 'palette' | 'grayscaleAlpha' | 'rgba';

/** 🎨️ One `PLTE` entry — a weak value (whole-value replaced in diffs). */
export interface PngRgb {
  r: number;
  g: number;
  b: number;
}

/** 👁️ Typed `tRNS` payload — shape depends on `colorType` (§11.3.3). */
export type PngTransparency =
  | { colorType: 'indexed'; alpha: number[] }
  | { colorType: 'grayscale'; gray: number }
  | { colorType: 'rgb'; r: number; g: number; b: number };

/** 📐️ `cHRM` — CIE xy chromaticity coordinates, each `value * 100000` (§11.3.5.2). */
export interface PngChromaticities {
  whiteX: number;
  whiteY: number;
  redX: number;
  redY: number;
  greenX: number;
  greenY: number;
  blueX: number;
  blueY: number;
}

/** 🖌️ `sRGB` rendering intent (§11.3.5.3). */
export type PngSrgbIntent = 'perceptual' | 'relativeColorimetric' | 'saturation' | 'absoluteColorimetric';

/** 📏️ `pHYs` — pixel-per-unit density (§11.3.5.4). */
export interface PngPhysicalDims {
  ppuX: number;
  ppuY: number;
  unitIsMeter: boolean;
}

/** 🕰️ `tIME` — last modification time, UTC (§11.3.6.1). */
export interface PngTimestamp {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second: number;
}

/** 🖼️ `bKGD` — default background color; shape depends on `colorType` (§11.3.5.1). */
export type PngBackground =
  | { colorType: 'grayscale'; gray: number }
  | { colorType: 'rgb'; r: number; g: number; b: number }
  | { colorType: 'indexed'; index: number };

/** 🔤 Which of the three PNG text chunk types (§11.3.4) a `PngTextChunk` came from. */
export type PngTextKind = 'text' | 'zText' | 'iText';

/** 💬️ One `tEXt`/`zTXt`/`iTXt` chunk. Index-keyed within `PngSnapshot.textChunks` — PNG
 * explicitly permits duplicate keywords, so keyword identity is unsound as a diff key.
 * `languageTag`/`translatedKeyword` are iTXt-only, empty string for `text`/`zText`. */
export interface PngTextChunk {
  keyword: string;
  value: string;
  compressed: boolean;
  kind: PngTextKind;
  languageTag: string;
  translatedKeyword: string;
}

/** 🗃️ A chunk the codec doesn't specifically model, retained verbatim. */
export interface PngChunk {
  kind: number[]; // 4-byte chunk type, e.g. [0x70,0x72,0x49,0x56] for "prIV"
  data: number[];
}

/** 🧭️ One slot in the file's real chunk sequence. `idat` coalesces every physical IDAT
 * chunk of the source file into one logical position. `text`/`unknown` carry the index into
 * `textChunks`/`unknownChunks` occupying this position. */
export type PngChunkMarker =
  | { chunk: 'ihdr' }
  | { chunk: 'plte' }
  | { chunk: 'trns' }
  | { chunk: 'gama' }
  | { chunk: 'chrm' }
  | { chunk: 'srgb' }
  | { chunk: 'phys' }
  | { chunk: 'time' }
  | { chunk: 'bkgd' }
  | { chunk: 'idat' }
  | { chunk: 'iend' }
  | { chunk: 'text'; index: number }
  | { chunk: 'unknown'; index: number };

/** 📸️ Complete `stdio.png` 1.2 semantic snapshot. `schema` is an identity field, never
 * diffed. IHDR compression method / filter method are always 0, validated on decode, never
 * modeled as mutable fields. `pixels` is always canonical 8-bit-per-channel RGBA, non-
 * interlaced regardless of the source file's own encoding. */
export interface PngSnapshot {
  schema: string;
  width: number;
  height: number;
  bitDepth: number;
  colorType: PngColorType;
  interlace: boolean;
  plte?: PngRgb[];
  trns?: PngTransparency;
  gama?: number;
  chrm?: PngChromaticities;
  srgb?: PngSrgbIntent;
  phys?: PngPhysicalDims;
  time?: PngTimestamp;
  bkgd?: PngBackground;
  textChunks: PngTextChunk[];
  pixels: number[];
  chunkOrder: PngChunkMarker[];
  unknownChunks: PngChunk[];
}

//! 🧬️ PngSnapshot schema — complete PNG 1.2 semantic model, real codecs. Ticket
//! 26/08/10/ARTIFACT-SYSTEM-OVERHAUL-REAL-CODECS-RUNTIME-REUSE-EVOLUTION: replaces the old
//! `RasterImage`-shaped stub (`width`/`height`/`rgba` only) with typed IHDR, PLTE, tRNS, the
//! full typed ancillary set (gAMA/cHRM/sRGB/pHYs/tIME/bKGD), name-duplicate-safe index-keyed
//! text chunks (tEXt/zTXt/iTXt), decoded pixels, and chunk-ORDER + unknown-chunk verbatim
//! retention so nothing real on disk is silently dropped (`## Snapshot completeness spec`).

use crate::artifacts::png::STDIO_PNG_DOCUMENT_SCHEMA;
use schema::ArtifactSchema;
use serde::{Deserialize, Serialize};

//#region ColorModel
/// 🎨️ PNG §11.2.2 `IHDR` color type. `Palette` requires a `PLTE` chunk; `compression method`
/// and `filter method` are always `0` per spec and are validated on decode, never modeled here.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub enum PngColorType {
    Grayscale,
    Rgb,
    Palette,
    GrayscaleAlpha,
    #[default]
    Rgba,
}

impl PngColorType {
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn from_u8(v: u8) -> Result<Self, String> {
        match v {
            0 => Ok(PngColorType::Grayscale),
            2 => Ok(PngColorType::Rgb),
            3 => Ok(PngColorType::Palette),
            4 => Ok(PngColorType::GrayscaleAlpha),
            6 => Ok(PngColorType::Rgba),
            _ => Err(format!("png: unsupported color type {v}")),
        }
    }
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn to_u8(self) -> u8 {
        match self {
            PngColorType::Grayscale => 0,
            PngColorType::Rgb => 2,
            PngColorType::Palette => 3,
            PngColorType::GrayscaleAlpha => 4,
            PngColorType::Rgba => 6,
        }
    }
    /// 🔢️ Samples per pixel before any palette indirection.
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn samples_per_pixel(self) -> usize {
        match self {
            PngColorType::Grayscale | PngColorType::Palette => 1,
            PngColorType::Rgb => 3,
            PngColorType::GrayscaleAlpha => 2,
            PngColorType::Rgba => 4,
        }
    }
}
//#endregion ColorModel

//#region Palette
/// 🎨️ One `PLTE` entry — a weak value (whole-value replaced in diffs, never sub-diffed).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct PngRgb {
    pub r: u8,
    pub g: u8,
    pub b: u8,
}
//#endregion Palette

//#region Transparency
/// 👁️ Typed `tRNS` payload — shape depends on `color_type` (§11.3.3). Grayscale/RGB store
/// full 16-bit samples per spec regardless of `bit_depth`; a whole-value weak entity.
