    pub fn from_u8(v: u8) -> Result<Self, String> {
        match v {
            0 => Ok(PngSrgbIntent::Perceptual),
            1 => Ok(PngSrgbIntent::RelativeColorimetric),
            2 => Ok(PngSrgbIntent::Saturation),
            3 => Ok(PngSrgbIntent::AbsoluteColorimetric),
