//#region HandcraftedArtifactCodecs
impl store::ArtifactDsl for PngSnapshot {
    const EXTENSION: &'static str = "png";
    fn envelope_id() -> &'static str {
        "stdio.png"
    }

    fn parse_dsl(text: &str) -> Result<Self, store::TextError> {
        let body = match store::semio_format::split_text_preamble(text) {
            Ok((_, rest)) => rest,
            Err(_) => text,
        };
        let hex: String = body.chars().filter(|c| !c.is_whitespace()).collect();
        if hex.len() % 2 != 0 {
            return Err(store::TextError::new("odd hex length", dsl::TextSpan::at(1, 1)));
        }
        let mut bytes = Vec::with_capacity(hex.len() / 2);
        let mut i = 0usize;
        while i < hex.len() {
            let byte = u8::from_str_radix(&hex[i..i + 2], 16).map_err(|e| store::TextError::new(format!("invalid hex: {e}"), dsl::TextSpan::at(1, 1)))?;
            bytes.push(byte);
            i += 2;
        }
        crate::artifacts::png::engine::decode_png(&bytes).map_err(|e| store::TextError::new(e, dsl::TextSpan::at(1, 1)))
    }

    fn print_dsl(&self) -> String {
        let bytes = crate::artifacts::png::engine::encode_png(self).unwrap_or_default();
        let body: String = bytes.iter().map(|b| format!("{b:02x}")).collect();
        let envelope = store::semio_format::SemioEnvelope::from_envelope_id(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Dsl, 1).expect("valid envelope_id");
        store::semio_format::wrap_text(&envelope, &body)
    }
}

impl store::ArtifactPack for PngSnapshot {
    fn encode_pack_with(&self, options: &store::PackEncodeOptions) -> Result<Vec<u8>, store::PackError> {
        let _ = options;
        let raw = crate::artifacts::png::engine::encode_png(self).map_err(|e| store::PackError::Schema(e))?;
        let envelope = store::semio_format::SemioEnvelope::from_envelope_id(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Pack, 1).map_err(|e| store::PackError::Schema(e.to_string()))?;
        Ok(store::semio_format::wrap_binary(&envelope, &raw))
    }

    fn decode_pack_with(bytes: &[u8], options: &store::PackDecodeOptions) -> Result<Self, store::PackError> {
        let (envelope, inner) = store::semio_format::unwrap_binary(bytes).map_err(|e| store::PackError::Schema(e.to_string()))?;
        if envelope.envelope_id() != <Self as store::ArtifactDsl>::envelope_id() {
            return Err(store::PackError::Schema(format!("pack envelope mismatch: expected {}, got {}", <Self as store::ArtifactDsl>::envelope_id(), envelope.envelope_id())));
        }
        let _ = options;
        crate::artifacts::png::engine::decode_png(&inner).map_err(|e| store::PackError::Schema(e))
    }
}
//#endregion HandcraftedArtifactCodecs

module Stdio_png_snapshot;

# Shared `.semio` binary envelope wrapping a stdio.png payload: the REAL PNG 1.2 file bytes
# (§5 signature + repeating length-prefixed CRC-32'd chunks) that
# crate::artifacts::png::engine::{encode_png,decode_png} produce/consume.

public type Envelope = unit {
    magic: bytes &size=8;                                   # 0x89 "SEM" CR LF SUB LF
    token_len: uint32 &byte-order=spicy::ByteOrder::Little;
    token: bytes &size=self.token_len;                      # UTF-8 "stdio.png.pack v1"
    payload: PngFile;
};

type PngFile = unit {
    png_signature: bytes &size=8;   # 0x89 "PNG" CR LF SUB LF
    chunks: Chunk[] &until($$.chunk_type == b"IEND");
};

# §5.3 — one chunk: 4-byte big-endian length, 4-byte ASCII type, `length` bytes of data,
# 4-byte CRC-32 over (type + data).
type Chunk = unit {
    length: uint32;
    chunk_type: bytes &size=4;
    data: bytes &size=self.length;
    crc32: uint32;
};

# §11.2.2 — the always-present image header (compression/filter method always 0, validated,
# not modeled as mutable fields upstream).
type IhdrBody = unit {
    width: uint32;
    height: uint32;
    bit_depth: uint8;
    color_type: uint8;
    compression_method: uint8;
    filter_method: uint8;
    interlace_method: uint8;
};

