        let mut snap = base.clone();
        apply_png_mutation(&mut snap, &PngMutation::RemoveTextChunk { index: 42 });
        assert_eq!(snap, base);
        apply_png_mutation(&mut snap, &PngMutation::RemoveUnknownChunk { index: 42 });
