// 🔺️ Sparse diff for stdio.png. Tri-state ancillary fields (trns/gama/chrm/srgb/phys/time/
// bkgd/plte): `*_present` false + field unset = unchanged; true + field unset = cleared.
message PngDiff {
  optional uint32 width = 1;
  optional uint32 height = 2;
  optional uint32 bit_depth = 3;
  optional semio.s_stdio_png.snapshot.PngColorType color_type = 4;
  optional bool interlace = 5;
  bool plte_present = 6;
  optional PngPlteDiff plte = 7;
  bool trns_present = 8;
  optional semio.s_stdio_png.snapshot.PngTransparency trns = 9;
  bool gama_present = 10;
  optional uint32 gama = 11;
  bool chrm_present = 12;
  optional semio.s_stdio_png.snapshot.PngChromaticities chrm = 13;
  bool srgb_present = 14;
  optional semio.s_stdio_png.snapshot.PngSrgbIntent srgb = 15;
  bool phys_present = 16;
  optional semio.s_stdio_png.snapshot.PngPhysicalDims phys = 17;
  bool time_present = 18;
  optional semio.s_stdio_png.snapshot.PngTimestamp time = 19;
  bool bkgd_present = 20;
  optional semio.s_stdio_png.snapshot.PngBackground bkgd = 21;
  optional PngTextChunksDiff text_chunks = 22;
  optional bytes pixels = 23;
  optional PngChunkOrderDiff chunk_order = 24;
  optional PngUnknownChunksDiff unknown_chunks = 25;
}

