    let modified = order
        .iter()
        .enumerate()
        .filter_map(|(pos, m)| match m {
            PngChunkMarker::Unknown { index } if *index >= at => Some(PngChunkOrderModified { index: pos, marker: PngChunkMarker::Unknown { index: index + 1 } }),
            _ => None,
