            let rr = r.read_u16_le()?;
            let g = r.read_u16_le()?;
            let b = r.read_u16_le()?;
            Ok(PngBackground::Rgb { r: rr, g, b })
        }
        2 => Ok(PngBackground::Indexed { index: r.read_u8()? }),
