        for r in 0..8 {
            col[r] = block[r * 8 + c];
        }
        let res = fdct_1d(&col);
        for r in 0..8 {
            tmp[r * 8 + c] = res[r];
        }
    }
    let mut out = [0f64; 64];
    for r in 0..8 {
        let mut row = [0f64; 8];
        row.copy_from_slice(&tmp[r * 8..r * 8 + 8]);
        out[r * 8..r * 8 + 8].copy_from_slice(&fdct_1d(&row));
    }
    out
}
