syntax = "proto3";
package semio.s_stdio_jpg.snapshot;

message JfifThumbnail {
  uint32 width = 1;
  uint32 height = 2;
  bytes rgb_data = 3;
}

message JpgFrameComponent {
  uint32 id = 1;
  uint32 h_sampling = 2;
  uint32 v_sampling = 3;
  uint32 quant_table_id = 4;
}

message JpgFrameHeader {
  uint32 precision = 1;
  uint32 width = 2;
  uint32 height = 3;
  repeated JpgFrameComponent components = 4;
}

message JpgQuantTable {
  uint32 id = 1;
  uint32 precision = 2;
  repeated uint32 values = 3; // exactly 64, zigzag scan order
}

enum JpgHuffmanClass {
  DC = 0;
  AC = 1;
}

message JpgHuffmanTable {
  uint32 id = 1;
  JpgHuffmanClass class = 2;
  bytes bits = 3; // exactly 16
  bytes values = 4;
}

message JpgSegment {
  uint32 marker = 1;
  bytes data = 2;
}

enum JfifDensityUnits {
  ASPECT = 0;
  PIXELS_PER_INCH = 1;
  PIXELS_PER_CM = 2;
}

message JpgSnapshot {
  string schema = 1;
  uint32 width = 2;
  uint32 height = 3;
  bytes pixels = 4;
  optional uint32 re_encode_quality = 5;
  uint32 jfif_version_major = 6;
  uint32 jfif_version_minor = 7;
  JfifDensityUnits jfif_density_units = 8;
  uint32 jfif_x_density = 9;
  uint32 jfif_y_density = 10;
  optional JfifThumbnail jfif_thumbnail = 11;
  optional JpgFrameHeader frame = 12;
  uint32 sof_marker = 13;
  bool arithmetic = 14;
  repeated JpgQuantTable quant_tables = 15;
  repeated JpgHuffmanTable huffman_tables = 16;
  optional uint32 restart_interval = 17;
  repeated JpgSegment other_segments = 18;
}

/** 🧬️ JpgSnapshot schema facet — mirrors 🦀️component.rs field-for-field. Complete JFIF 1.01
 * semantic model: typed JFIF APP0, typed SOF (frame) + id-keyed DQT/DHT tables, DRI restart
 * interval, verbatim-retained other APPn/COM segments, decoded pixels. */

/** 📏️ JFIF APP0 `units` byte. `aspect` means x/y density are merely a pixel aspect ratio. */
export type JfifDensityUnits = 'aspect' | 'pixelsPerInch' | 'pixelsPerCm';

/** 🖼️ JFIF APP0's optional embedded thumbnail — uncompressed 24-bit RGB, `width * height * 3`
 * bytes, row-major. A weak value (whole-value replaced in diffs). */
export interface JfifThumbnail {
  width: number;
  height: number;
  rgbData: number[];
}

/** 🧩️ One SOF0 frame component descriptor. Id-keyed within `JpgFrameHeader.components`. */
export interface JpgFrameComponent {
  id: number;
  hSampling: number;
  vSampling: number;
  quantTableId: number;
}

/** 🖼️ Baseline (SOF0) frame header. */
export interface JpgFrameHeader {
  precision: number;
  width: number;
  height: number;
  components: JpgFrameComponent[];
}

/** 📊️ One `DQT` table (id-keyed within `JpgSnapshot.quantTables`). `values` is retained in the
 * EXACT zigzag scan order the DQT segment stores on disk. */
export interface JpgQuantTable {
  id: number;
  /** DQT `Pq` nibble: `0` = 8-bit values, `1` = 16-bit values. */
  precision: number;
  values: number[]; // exactly 64 entries
}

/** 🌳️ `DHT` table class. */
export type JpgHuffmanClass = 'dc' | 'ac';

/** 🌳️ One `DHT` table, keyed by `(class, id)` within `JpgSnapshot.huffmanTables`. */
export interface JpgHuffmanTable {
  id: number;
  class: JpgHuffmanClass;
  bits: number[]; // exactly 16 entries
  values: number[];
}

/** 🗃️ An APPn (other than a recognized JFIF APP0)/COM segment retained VERBATIM. Index-keyed
 * within `JpgSnapshot.otherSegments` — duplicate markers are legal. */
export interface JpgSegment {
  marker: number;
  data: number[];
}

/** 📸️ Complete `stdio.jpg` jfif-1.01 semantic snapshot. `schema` is an identity field, never
 * diffed. `frame`/`sofMarker`/`arithmetic` are populated by decode (undefined/0/false only for a
 * snapshot that has never round-tripped through a real JPEG byte stream). `width`/`height`/
 * `pixels` are the canonical raster (8-bit RGBA, `width * height * 4` bytes) — distinct from
 * `frame.width`/`frame.height` (on-disk SOF values). */
export interface JpgSnapshot {
  schema: string;
  width: number;
  height: number;
  pixels: number[];
  reEncodeQuality?: number;
  jfifVersion: [number, number];
  jfifDensityUnits: JfifDensityUnits;
  jfifXDensity: number;
  jfifYDensity: number;
  jfifThumbnail?: JfifThumbnail;
  frame?: JpgFrameHeader;
  sofMarker: number;
  arithmetic: boolean;
  quantTables: JpgQuantTable[];
  huffmanTables: JpgHuffmanTable[];
  restartInterval?: number;
  otherSegments: JpgSegment[];
}

//! 🧬️ JpgSnapshot schema — complete JFIF 1.01 semantic model, real codecs. Ticket
//! 26/08/10/ARTIFACT-SYSTEM-OVERHAUL-REAL-CODECS-RUNTIME-REUSE-EVOLUTION: replaces the old
//! `RasterImage`-shaped stub (`image: RasterImage{width,height,rgba}` only, no JFIF/SOF/DQT/DHT
//! typing at all) with a typed JFIF APP0 header, typed SOF (frame) + id-keyed DQT/DHT tables,
//! `DRI` restart interval, verbatim-retained other APPn/COM segments, and decoded pixels —
//! `## Snapshot completeness spec`'s jpg row. `RasterImage` itself dies per the ticket's explicit
//! kill directive (W0: "shared verbatim across jpg/png/tiff, png already killed its own copy") —
//! `width`/`height`/`pixels` are first-class fields here, no shared wrapper type.

use crate::artifacts::jpg::STDIO_JPG_DOCUMENT_SCHEMA;
use schema::ArtifactSchema;
use serde::{Deserialize, Serialize};

//#region Jfif
/// 📏️ JFIF APP0 `units` byte (ITU-T T.871 / JFIF 1.02 §). `Aspect` means `x_density`/
/// `y_density` are merely a pixel aspect ratio, not an absolute resolution.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub enum JfifDensityUnits {
    #[default]
    Aspect,
    PixelsPerInch,
    PixelsPerCm,
}

impl JfifDensityUnits {
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn from_u8(v: u8) -> Result<Self, String> {
        match v {
            0 => Ok(JfifDensityUnits::Aspect),
            1 => Ok(JfifDensityUnits::PixelsPerInch),
            2 => Ok(JfifDensityUnits::PixelsPerCm),
            _ => Err(format!("jfif: unsupported density unit {v}")),
        }
    }
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn to_u8(self) -> u8 {
        match self {
            JfifDensityUnits::Aspect => 0,
            JfifDensityUnits::PixelsPerInch => 1,
            JfifDensityUnits::PixelsPerCm => 2,
        }
    }
}

/// 🖼️ JFIF APP0's optional embedded thumbnail — uncompressed 24-bit RGB, `width * height * 3`
