//#region HandcraftedArtifactCodecs
impl store::ArtifactDsl for JpgSnapshot {
    const EXTENSION: &'static str = "jpg";
    fn envelope_id() -> &'static str {
        "stdio.jpg"
    }

    fn parse_dsl(text: &str) -> Result<Self, store::TextError> {
        let body = match store::semio_format::split_text_preamble(text) {
            Ok((_, rest)) => rest,
            Err(_) => text,
        };
        let hex: String = body.chars().filter(|c| !c.is_whitespace()).collect();
        if hex.len() % 2 != 0 {
            return Err(store::TextError::new("odd hex length", dsl::TextSpan::at(1, 1)));
        }
        let mut bytes = Vec::with_capacity(hex.len() / 2);
        let mut i = 0usize;
        while i < hex.len() {
            let byte = u8::from_str_radix(&hex[i..i + 2], 16).map_err(|e| store::TextError::new(format!("invalid hex: {e}"), dsl::TextSpan::at(1, 1)))?;
            bytes.push(byte);
            i += 2;
        }
        crate::artifacts::jpg::engine::decode_jpg(&bytes).map_err(|e| store::TextError::new(e.to_string(), dsl::TextSpan::at(1, 1)))
    }

    fn print_dsl(&self) -> String {
        let bytes = crate::artifacts::jpg::engine::encode_jpg(self).unwrap_or_default();
        let body: String = bytes.iter().map(|b| format!("{b:02x}")).collect();
        let envelope = store::semio_format::SemioEnvelope::from_envelope_id(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Dsl, 1).expect("valid envelope_id");
        store::semio_format::wrap_text(&envelope, &body)
    }
}

impl store::ArtifactPack for JpgSnapshot {
    fn encode_pack_with(&self, options: &store::PackEncodeOptions) -> Result<Vec<u8>, store::PackError> {
        let _ = options;
        let raw = crate::artifacts::jpg::engine::encode_jpg(self).map_err(|e| store::PackError::Schema(e.to_string()))?;
        let envelope = store::semio_format::SemioEnvelope::from_envelope_id(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Pack, 1).map_err(|e| store::PackError::Schema(e.to_string()))?;
        Ok(store::semio_format::wrap_binary(&envelope, &raw))
    }

    fn decode_pack_with(bytes: &[u8], options: &store::PackDecodeOptions) -> Result<Self, store::PackError> {
        let (envelope, inner) = store::semio_format::unwrap_binary(bytes).map_err(|e| store::PackError::Schema(e.to_string()))?;
        if envelope.envelope_id() != <Self as store::ArtifactDsl>::envelope_id() {
            return Err(store::PackError::Schema(format!("pack envelope mismatch: expected {}, got {}", <Self as store::ArtifactDsl>::envelope_id(), envelope.envelope_id())));
        }
        let _ = options;
        crate::artifacts::jpg::engine::decode_jpg(&inner).map_err(|e| store::PackError::Schema(e.to_string()))
    }
}
//#endregion HandcraftedArtifactCodecs

module Stdio_jpg_snapshot;

# 🌶️ Real pack encoding: semio binary envelope wrapping the ACTUAL JFIF byte stream
# `engine::decode_jpg` parses (ITU-T T.81 marker-segment structure), not a raw byte blob.

public type Envelope = unit {
    magic: bytes &size=4;               # "SEMI"
    header: bytes &size=28;             # schema id / component / version / payload length
    jpeg: JpegStream;
};

type JpegStream = unit {
    soi: bytes &size=2;                 # 0xFF 0xD8
    segments: Segment[] &until($$.marker == 0xDA);
    sos: SosSegment;
    entropy_and_eoi: bytes &eod;        # byte-stuffed entropy-coded scan + trailing EOI (0xFFD9);
                                         # a real entropy decoder must byte-destuff and watch for
                                         # restart/EOI markers inline (this codec's `decode_scan`)
};

type Segment = unit {
    prefix: uint8 &requires=(self.prefix == 0xFF);
    marker: uint8;
    length: uint16;
    body: bytes &size=self.length - 2;
};

type SosSegment = unit {
    prefix: bytes &size=2;              # 0xFF 0xDA
    length: uint16;
    num_components: uint8;
    components: ScanComponent[self.num_components];
    spectral_start: uint8;
    spectral_end: uint8;
    approx: uint8;
};

type ScanComponent = unit {
    component_id: uint8;
    dc_ac_table: uint8;
};

