//! 📝️ Text representation codec surface for `stdio.jpg` (snapshot).

/// 📖️ Grammar include.
pub const COMPONENT_GRAMMAR_SEMIO: &str = include_str!("📖️component.grammar.semio");
pub const COMPONENT_GRAMMAR_PATH: &str = concat!(module_path!(), "::📖️component.grammar.semio");

grammar Stdio_jpg_snapshot;
// 🅰️ TEXT envelope: a semio preamble line, then the real JFIF byte stream hex-encoded
// (ITU-T T.81/ISO 10918-1) -- what `store::ArtifactDsl::parse_dsl`/`print_dsl` actually
// round-trip, not a placeholder octet blob.

document   : preamble NEWLINE payload EOF ;
preamble   : 'semio' WS 'dsl' WS INT WS 'stdio.jpg' ;
payload    : HEXBYTE* ;                 // hex-decodes to a real jpeg-stream, see the
                                          // 📖 grammar.semio leaf for the marker-segment shape
HEXBYTE    : [0-9a-fA-F] [0-9a-fA-F] ;
INT        : [0-9]+ ;
WS         : [ \t]+ ;
NEWLINE    : '\r'? '\n' ;

(* ebnf stdio.jpg snapshot -- semio preamble + the real JFIF byte stream hex-encoded (ITU-T
   T.81/ISO 10918-1), not a placeholder octet blob. *)
document = preamble, newline, payload ;
preamble = "semio", space, "dsl", space, integer, space, "stdio.jpg" ;
payload = { hex byte } ;                 (* hex-decodes to a real marker-segment jpeg stream *)
jpeg stream = SOI, { segment }, app0, { segment }, sof0, { segment }, sos, entropy data, EOI ;
SOI = "0xFF", "0xD8" ;
EOI = "0xFF", "0xD9" ;
segment = marker, length, body ;
app0 = "0xFF", "0xE0", length, "JFIF", "0x00", version, units, x density, y density, thumb dims, thumb rgb ;
sof0 = "0xFF", "0xC0", length, precision, height, width, n components, component, { component } ;
sos = "0xFF", "0xDA", length, n scan components, scan component, { scan component }, Ss, Se, AhAl ;

