    //#region 🔖️kinds_matches_enum_and_manifest
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    fn kind_of(m: &JpgMutation) -> &'static str {
        match m {
            JpgMutation::NoMutation => "no-mutation",
            JpgMutation::SetSnapshot { .. } => "set-snapshot",
            JpgMutation::SetJfifHeader { .. } => "set-jfif-header",
            JpgMutation::SetQuantTable { .. } => "set-quant-table",
            JpgMutation::RemoveQuantTable { .. } => "remove-quant-table",
            JpgMutation::SetHuffmanTable { .. } => "set-huffman-table",
            JpgMutation::RemoveHuffmanTable { .. } => "remove-huffman-table",
            JpgMutation::SetRestartInterval { .. } => "set-restart-interval",
            JpgMutation::InsertOtherSegment { .. } => "insert-other-segment",
            JpgMutation::RemoveOtherSegment { .. } => "remove-other-segment",
            JpgMutation::SetPixels { .. } => "set-pixels",
            JpgMutation::SetReEncodeQuality { .. } => "set-re-encode-quality",
        }
    }

    /// 🧪️ `KINDS` must name exactly the enum's own variants (the match above is exhaustive, so a
    /// variant added without updating `kind_of` fails to compile) AND exactly the mutation catalog's
    /// declared `kinds` — the framework never parses Rust, so this test is what keeps the manifest
    /// honest.
    #[test]
    fn kinds_matches_enum_variants_and_manifest() {
        let base = base_snapshot();
        let mut from_enum: Vec<&str> = all_variants(&base).iter().map(kind_of).collect();
        from_enum.sort_unstable();
        from_enum.dedup();
        let mut from_const = KINDS.to_vec();
        from_const.sort_unstable();
        assert_eq!(from_const, from_enum, "KINDS must name exactly the enum's variants");

        let manifest: serde_json::Value = serde_json::from_str(include_str!("../../🧪️oracle/🔣️component.json")).expect("valid oracle manifest JSON");
        let mut from_manifest: Vec<String> = manifest["mutationCatalogs"][0]["kinds"].as_array().expect("mutationCatalogs[0].kinds").iter().map(|value| value.as_str().expect("kind is a string").to_string()).collect();
        from_manifest.sort_unstable();
        assert_eq!(from_const, from_manifest.iter().map(String::as_str).collect::<Vec<_>>(), "KINDS must name exactly the manifest's declared kinds");
    }
    //#endregion 🔖️kinds_matches_enum_and_manifest

    //#region 🔖️absorb_law
    fn assert_absorb_law(base: &JpgSnapshot, m1: JpgMutation, m2: JpgMutation) {
        let d1 = m1.diff(base);
        let mid = d1.diff().apply(base).expect("d1 must apply to base");
        let d2 = m2.diff(&mid);
        let sequential = d2.diff().apply(&mid).expect("d2 must apply to mid");

        let mut merged = d1.diff().clone();
        merged.absorb(d2.diff().clone());
        assert_eq!(merged.apply(base).expect("merged diff must apply to base"), sequential, "absorb(d1,d2).apply(base) must equal sequential application for {m1:?} + {m2:?}");
    }

    #[test]
    fn absorb_law() {
        let base = base_snapshot();

        // Insert+Remove-before: other_segments has [seg@0]; insert at 1 -> [seg,new]; then
        // remove index 0 ("seg") -> [new] lands at final index 0 (the recipe's own canonical case).
        assert_absorb_law(&base, JpgMutation::InsertOtherSegment { index: 1, segment: segment(0xE3, vec![1]) }, JpgMutation::RemoveOtherSegment { index: 0 });

        // Insert+Insert-same-index: both survive.
        assert_absorb_law(&base, JpgMutation::InsertOtherSegment { index: 1, segment: segment(0xE4, vec![2]) }, JpgMutation::InsertOtherSegment { index: 1, segment: segment(0xE5, vec![3]) });

        // Add+SetField: the second mutation patches directly into the still-pending added table.
        assert_absorb_law(&base, JpgMutation::SetQuantTable { table: quant(5, 1) }, JpgMutation::SetQuantTable { table: quant(5, 2) });

        // Modify+Remove: a pending field patch on a since-removed base item vanishes.
        assert_absorb_law(&base, JpgMutation::SetQuantTable { table: quant(0, 42) }, JpgMutation::RemoveQuantTable { id: 0 });

        // Insert then annihilate the very same insert — huffman_tables' id-keyed transport.
        assert_absorb_law(&base, JpgMutation::SetHuffmanTable { table: huffman(JpgHuffmanClass::Ac, 3, 1) }, JpgMutation::RemoveHuffmanTable { key: HKey { class: JpgHuffmanClass::Ac, id: 3 } });

        // Two unrelated scalar sets absorb via LWW.
        assert_absorb_law(&base, JpgMutation::SetRestartInterval { restart_interval: Some(1) }, JpgMutation::SetRestartInterval { restart_interval: Some(2) });

        // Tri-state set-then-clear: the later clear wins outright over the pending set.
        assert_absorb_law(&base, JpgMutation::SetReEncodeQuality { quality: Some(10) }, JpgMutation::SetReEncodeQuality { quality: None });
    }

    #[test]
    fn absorb_law_associativity() {
        let base = base_snapshot();
        let d1 = JpgMutation::SetQuantTable { table: quant(7, 1) }.diff(&base);
        let s1 = d1.diff().apply(&base).expect("d1 must apply to base");
        let d2 = JpgMutation::SetQuantTable { table: quant(7, 2) }.diff(&s1);
        let s2 = d2.diff().apply(&s1).expect("d2 must apply to s1");
        let d3 = JpgMutation::RemoveQuantTable { id: 0 }.diff(&s2);
        let s3 = d3.diff().apply(&s2).expect("d3 must apply to s2");

        // (d1∘d2)∘d3
        let mut left = d1.diff().clone();
        left.absorb(d2.diff().clone());
        left.absorb(d3.diff().clone());

        // d1∘(d2∘d3)
        let mut d23 = d2.diff().clone();
        d23.absorb(d3.diff().clone());
        let mut right = d1.diff().clone();
        right.absorb(d23);

        assert_eq!(left.apply(&base).expect("left must apply to base"), s3);
        assert_eq!(right.apply(&base).expect("right must apply to base"), s3);
        assert_eq!(left.apply(&base).expect("left must apply to base"), right.apply(&base).expect("right must apply to base"), "absorb must associate");
    }
    //#endregion 🔖️absorb_law

