export interface JpgHuffmanTableModified { key: JpgHuffmanTableKey; diff: JpgHuffmanTableDiff }
export interface JpgHuffmanTableAdded { index: number; item: JpgHuffmanTable }
export interface JpgHuffmanTablesDiff {
