    /// from a throwaway type-checking crate outside the real oracle crate's tree during review).
    fn find_repo_root(start: &std::path::Path) -> std::path::PathBuf {
        let mut dir = start.to_path_buf();
        for _ in 0..32 {
            if dir.join("CLAUDE.md").is_file() {
                return dir;
            }
            if !dir.pop() {
                break;
