            png::ColorType::Rgba => buf[..frame.buffer_size()].to_vec(),
            png::ColorType::Rgb => buf[..frame.buffer_size()].chunks_exact(3).flat_map(|p| [p[0], p[1], p[2], 255]).collect(),
