syntax = "proto3";
package semio.s_stdio_tiff.snapshot;

enum TiffByteOrder {
  TIFF_BYTE_ORDER_UNSPECIFIED = 0;
  LITTLE_ENDIAN = 1;
  BIG_ENDIAN = 2;
}

// TIFF6 §2 Table 2 — the 12 real IFD entry field types.
enum TiffFieldType {
  TIFF_FIELD_TYPE_UNSPECIFIED = 0;
  BYTE = 1;
  ASCII = 2;
  SHORT = 3;
  LONG = 4;
  RATIONAL = 5;
  S_BYTE = 6;
  UNDEFINED = 7;
  S_SHORT = 8;
  S_LONG = 9;
  S_RATIONAL = 10;
  FLOAT = 11;
  DOUBLE = 12;
}

// One numerator/denominator pair (RATIONAL/S_RATIONAL element).
message TiffRationalPair {
  int64 numerator = 1;
  int64 denominator = 2;
}

// Typed union over every TIFF 6.0 field type's decoded value — `kind` selects which ONE of the
// typed fields below is populated (mirrors the adjacently-tagged `{kind,value}` Rust/JSON
// shape; proto3 `oneof` can't hold `repeated` members directly, so this stays a flat message).
message TiffValues {
  TiffFieldType kind = 1;
  repeated uint32 byte_value = 2;
  string ascii_value = 3;
  repeated uint32 short_value = 4;
  repeated uint32 long_value = 5;
  repeated TiffRationalPair rational_value = 6;
  repeated int32 s_byte_value = 7;
  repeated uint32 undefined_value = 8;
  repeated int32 s_short_value = 9;
  repeated int32 s_long_value = 10;
  repeated TiffRationalPair s_rational_value = 11;
  repeated float float_value = 12;
  repeated double double_value = 13;
}

// One IFD entry — a weak value (whole-value replaced in diffs).
message TiffTag {
  uint32 tag = 1;
  TiffFieldType kind = 2;
  TiffValues values = 3;
}

// One Image File Directory — tag-id-keyed entries (TIFF requires ascending-tag-order).
message TiffIfd {
  repeated TiffTag entries = 1;
  // This directory's own raster as RAW STRIP BYTES; empty for IFD 0 and for a metadata-only directory.
  bytes pixels = 2;
}

// Complete `stdio.tiff` 6.0 semantic snapshot. `pixels` is the decoded raster payload
// (canonical 8-bit RGBA, decoded from IFD 0 only).
message TiffSnapshot {
  string schema = 1;
  TiffByteOrder byte_order = 2;
  repeated TiffIfd ifds = 3;
  bytes pixels = 4;
}

/** 🧬️ TiffSnapshot schema facet — mirrors 🦀️component.rs field-for-field. Complete TIFF 6.0
 * semantic model: `byteOrder` + index-keyed `ifds`, each holding tag-id-keyed typed tag/type/
 * value entries — TIFF's own generic model ("unknown tags" are just tags this codec doesn't
 * specially interpret, but whose typed value is still stored losslessly via this same
 * triple), plus decoded `pixels`. */

export type TiffByteOrder = 'littleEndian' | 'bigEndian';

/** 🏷️ TIFF6 §2 Table 2 — the 12 real IFD entry field types. */
export type TiffFieldType =
  | 'byte' | 'ascii' | 'short' | 'long' | 'rational' | 'sByte'
  | 'undefined' | 'sShort' | 'sLong' | 'sRational' | 'float' | 'double';

/** 📦️ Typed union over every TIFF 6.0 field type's decoded value — adjacently tagged
 * (`kind`/`value`), mirroring the Rust enum's `#[serde(tag = "kind", content = "value")]`. */
export type TiffValues =
  | { kind: 'byte'; value: number[] }
  | { kind: 'ascii'; value: string }
  | { kind: 'short'; value: number[] }
  | { kind: 'long'; value: number[] }
  | { kind: 'rational'; value: [number, number][] }
  | { kind: 'sByte'; value: number[] }
  | { kind: 'undefined'; value: number[] }
  | { kind: 'sShort'; value: number[] }
  | { kind: 'sLong'; value: number[] }
  | { kind: 'sRational'; value: [number, number][] }
  | { kind: 'float'; value: number[] }
  | { kind: 'double'; value: number[] };

/** 🏷️ One IFD entry — a weak value (whole-value replaced in diffs: `kind`/`values` move
 * together atomically). */
export interface TiffTag {
  tag: number;
  kind: TiffFieldType;
  values: TiffValues;
}

/** 🗂️ One Image File Directory — tag-id-keyed `entries` (TIFF requires ascending-tag-order). */
export interface TiffIfd {
  entries: TiffTag[];
  /** This directory's own raster as RAW STRIP BYTES; empty for IFD 0 (whose raster is the
   * snapshot's own canonical RGBA `pixels`) and for a metadata-only directory. */
  pixels: number[];
}

/** 📸️ Complete `stdio.tiff` 6.0 semantic snapshot. `schema` is an identity field, never
 * diffed. `pixels` is the decoded raster payload (canonical 8-bit RGBA, decoded from IFD 0
 * only — see the Rust engine's doc for the full completeness accounting). */
export interface TiffSnapshot {
  schema: string;
  byteOrder: TiffByteOrder;
  ifds: TiffIfd[];
  pixels: number[];
}

//! 🧬️ TiffSnapshot schema — complete TIFF 6.0 semantic model. Ticket
//! 26/08/10/ARTIFACT-SYSTEM-OVERHAUL-REAL-CODECS-RUNTIME-REUSE-EVOLUTION: replaces the old
//! shared `RasterImage{width,height,rgba}` stub with TIFF's REAL generic tag/type/value model:
//! `byte_order` + index-keyed `ifds: Vec<TiffIfd>`, each holding tag-id-keyed `TiffTag{tag,
//! kind, values}` entries. `TiffFieldType`/`TiffValues` cover all 12 TIFF 6.0 field types —
//! "unknown tags" are simply tags the codec doesn't specially interpret, but whose typed
//! VALUE is still stored losslessly via this same triple (the tag/type/value model IS the
//! raw-retention mechanism; no separate raw-bytes fallback needed, unlike PNG's
//! `unknown_chunks`). Decoded pixels stay a flat `pixels: Vec<u8>` (documented normalization:
//! canonical 8-bit RGBA, row-major, decoded from IFD 0 only — see `../../🚪️io/🦀️component.rs`'s
//! `MultiIfdEncodeScopeNote`/decode doc for the full completeness accounting, including the honest
//! gap that this single `pixels` field cannot back a real raster for any IFD beyond the first).

use crate::artifacts::tiff::STDIO_TIFF_DOCUMENT_SCHEMA;
use schema::ArtifactSchema;
use serde::{Deserialize, Serialize};

//#region ByteOrder
/// 🧭️ TIFF6 §2 byte-order mark (`II` little-endian / `MM` big-endian) — governs every
/// multi-byte field in the file, including every IFD entry's `count`/inline value bytes.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub enum TiffByteOrder {
    #[default]
    LittleEndian,
    BigEndian,
}
//#endregion ByteOrder

//#region FieldType
/// 🏷️ TIFF6 §2 Table 2 — the 12 real IFD entry field types. Type code 13 (`IFD`) is a later
/// extension outside the 6.0 core table and is deliberately NOT modeled (decode errors
/// honestly rather than fabricating a 13th variant this standard doesn't claim).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum TiffFieldType {
    Byte,
    Ascii,
    Short,
    Long,
    Rational,
    SByte,
    Undefined,
    SShort,
    SLong,
    SRational,
    Float,
    Double,
}

impl TiffFieldType {
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn from_u16(v: u16) -> Result<Self, String> {
        match v {
            1 => Ok(Self::Byte),
            2 => Ok(Self::Ascii),
            3 => Ok(Self::Short),
            4 => Ok(Self::Long),
            5 => Ok(Self::Rational),
            6 => Ok(Self::SByte),
            7 => Ok(Self::Undefined),
            8 => Ok(Self::SShort),
            9 => Ok(Self::SLong),
            10 => Ok(Self::SRational),
            11 => Ok(Self::Float),
            12 => Ok(Self::Double),
            other => Err(format!("tiff: unrecognized field type code {other} (TIFF 6.0 core table is 1-12)")),
        }
    }
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn to_u16(self) -> u16 {
        match self {
            Self::Byte => 1,
            Self::Ascii => 2,
            Self::Short => 3,
            Self::Long => 4,
            Self::Rational => 5,
            Self::SByte => 6,
            Self::Undefined => 7,
            Self::SShort => 8,
            Self::SLong => 9,
            Self::SRational => 10,
            Self::Float => 11,
            Self::Double => 12,
        }
    }
    /// 📏️ Byte size of ONE value of this type (TIFF6 §2 Table 2) — drives the inline-vs-offset
    /// rule (`element_size * count <= 4` stays inline in the entry's value field).
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn element_size(self) -> usize {
        match self {
            Self::Byte | Self::Ascii | Self::SByte | Self::Undefined => 1,
            Self::Short | Self::SShort => 2,
            Self::Long | Self::SLong | Self::Float => 4,
            Self::Rational | Self::SRational | Self::Double => 8,
        }
    }
}
//#endregion FieldType

//#region Values
/// 📦️ Typed union over every TIFF 6.0 field type's decoded value — the tag/type/value TRIPLE
/// (with [`TiffTag::tag`]/[`TiffTag::kind`]) is what makes an "unknown" tag still losslessly
/// retained: the codec doesn't need to specially interpret a tag id to store its real typed
/// value honestly. Adjacently tagged (`kind`/`value`) rather than internally tagged so these
/// newtype variants (all of which wrap arrays/strings, not structs) serialize cleanly — same
/// pattern as `ply`'s `PlyValue`.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", content = "value", rename_all = "camelCase")]
pub enum TiffValues {
    Byte(Vec<u8>),
    Ascii(String),
    Short(Vec<u16>),
    Long(Vec<u32>),
    Rational(Vec<(u32, u32)>),
    SByte(Vec<i8>),
    Undefined(Vec<u8>),
    SShort(Vec<i16>),
    SLong(Vec<i32>),
    SRational(Vec<(i32, i32)>),
    Float(Vec<f32>),
    Double(Vec<f64>),
}

impl TiffValues {
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn kind(&self) -> TiffFieldType {
        match self {
            Self::Byte(_) => TiffFieldType::Byte,
            Self::Ascii(_) => TiffFieldType::Ascii,
            Self::Short(_) => TiffFieldType::Short,
            Self::Long(_) => TiffFieldType::Long,
            Self::Rational(_) => TiffFieldType::Rational,
            Self::SByte(_) => TiffFieldType::SByte,
            Self::Undefined(_) => TiffFieldType::Undefined,
            Self::SShort(_) => TiffFieldType::SShort,
            Self::SLong(_) => TiffFieldType::SLong,
            Self::SRational(_) => TiffFieldType::SRational,
            Self::Float(_) => TiffFieldType::Float,
            Self::Double(_) => TiffFieldType::Double,
        }
    }
    /// 🔢️ IFD entry `Count` for this value — number of elements of `kind()`, EXCEPT `Ascii`
    /// which counts BYTES including the terminating NUL (TIFF6 §2's own special case).
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn count(&self) -> u32 {
        match self {
            Self::Byte(v) => v.len() as u32,
            Self::Ascii(s) => s.len() as u32 + 1,
            Self::Short(v) => v.len() as u32,
            Self::Long(v) => v.len() as u32,
            Self::Rational(v) => v.len() as u32,
            Self::SByte(v) => v.len() as u32,
            Self::Undefined(v) => v.len() as u32,
            Self::SShort(v) => v.len() as u32,
            Self::SLong(v) => v.len() as u32,
            Self::SRational(v) => v.len() as u32,
            Self::Float(v) => v.len() as u32,
            Self::Double(v) => v.len() as u32,
        }
    }
    /// 🔍️ First value widened to `u32`, for integer-typed variants only — convenience used by
    /// well-known-tag accessors ([`TiffSnapshot::width`] etc.) and the baseline subset's
    /// conformance checks. `None` for non-integer/empty variants.
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn first_u32(&self) -> Option<u32> {
        match self {
            Self::Byte(v) => v.first().map(|&x| x as u32),
            Self::Short(v) => v.first().map(|&x| x as u32),
            Self::Long(v) => v.first().copied(),
            Self::SByte(v) => v.first().map(|&x| x as u32),
            Self::SShort(v) => v.first().map(|&x| x as u32),
            Self::SLong(v) => v.first().map(|&x| x as u32),
            _ => None,
        }
    }
}
//#endregion Values

//#region Tag
/// 🏷️ One IFD entry — a weak value (whole-value replaced in diffs: `kind`/`values` move
/// together atomically, never sub-diffed).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TiffTag {
    pub tag: u16,
    pub kind: TiffFieldType,
    pub values: TiffValues,
}
//#endregion Tag

//#region Ifd
/// 🗂️ One Image File Directory — tag-id-keyed `entries` (TIFF requires ascending-tag-order
/// within an IFD; codecs/mutations both maintain that invariant, see `⚙️engine`/`🔺️diff`) plus
/// `pixels`, this directory's OWN raster payload.
///
/// 🖼️ `pixels` is RAW STRIP BYTES — the exact sample layout this directory's own
/// `BitsPerSample`/`SamplesPerPixel`/`PhotometricInterpretation`/`Compression` entries declare —
/// NOT the canonical 8-bit RGBA [`TiffSnapshot::pixels`] carries. Raw is the honest shape here:
/// strip bytes are lossless and layout-agnostic, so a secondary directory whose photometric
/// layout this codec does not decode (palette, CMYK, tiled) still round-trips byte-for-byte,
/// where a decode-to-RGBA field would have to fail or fabricate.
///
/// 🥇 IFD 0 is the exception, and it is a definitional one rather than an omission: the primary
/// directory's raster IS the document's image, is decoded to canonical RGBA into
/// [`TiffSnapshot::pixels`], and is the field `SetPixels` addresses. `ifds[0].pixels` is therefore
/// always empty — decode leaves it so, the encoder ignores it, and there is exactly one authority
/// for the primary raster at all times. Every directory beyond the first carries its strip bytes
/// here, which is what lets the encoder emit that directory's REQUIRED
/// `StripOffsets`/`RowsPerStrip`/`StripByteCounts` (TIFF6 §Baseline) backed by real payload rather
/// than omit them (the pre-2026-08-25 behaviour, which silently discarded a multi-page file's
/// later pages on every round trip).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct TiffIfd {
    #[serde(default)]
    pub entries: Vec<TiffTag>,
    #[serde(default)]
    pub pixels: Vec<u8>,
}
//#endregion Ifd

//#region WellKnownTags
/// 📌️ TIFF6 §8/§19 baseline tag ids `⚙️engine`/`🧐️analyzer` (✳️any + ✳️baseline) share by name.
pub const TAG_IMAGE_WIDTH: u16 = 256;
pub const TAG_IMAGE_LENGTH: u16 = 257;
pub const TAG_BITS_PER_SAMPLE: u16 = 258;
pub const TAG_COMPRESSION: u16 = 259;
pub const TAG_PHOTOMETRIC: u16 = 262;
pub const TAG_STRIP_OFFSETS: u16 = 273;
pub const TAG_SAMPLES_PER_PIXEL: u16 = 277;
pub const TAG_ROWS_PER_STRIP: u16 = 278;
pub const TAG_STRIP_BYTE_COUNTS: u16 = 279;
pub const TAG_TILE_WIDTH: u16 = 322;
pub const TAG_TILE_LENGTH: u16 = 323;
