            TiffMutation::SetTag { ifd_index: 0, tag: 0, kind: TiffFieldType::Byte, values: TiffValues::Byte(vec![]) },
            TiffMutation::RemoveTag { ifd_index: 0, tag: 0 },
            TiffMutation::SetPixels { pixels: vec![] },
        ]
    }

