// 🅰️ `TiffDiff`'s wire text IS its JSON serialization (serde `camelCase`, sparse — see
// 🦀️component.rs). This grammar names the real top-level fields rather than a placeholder;
// it does not restate RFC 8259's own JSON grammar in full.
grammar Stdio_tiff_diff;

diff       : '{' member (',' member)* '}' | '{' '}' ;
member     : BYTE_ORDER ':' STRING | IFDS ':' ifdsTriple | PIXELS ':' '[' INT* ']' ;
ifdsTriple : '{' '}' | '{' 'removed' ':' '[' INT* ']' (',' 'modified' ':' '[' ifdModified* ']')? (',' 'added' ':' '[' value* ']')? '}' ;
ifdModified: '{' 'index' ':' INT ',' 'diff' ':' tagsTriple '}' ;
tagsTriple : '{' '}' | '{' 'removed' ':' '[' INT* ']' (',' 'modified' ':' '[' value* ']')? (',' 'added' ':' '[' value* ']')? '}' ;
value      : '{' member2 (',' member2)* '}' | STRING | INT | BOOL | 'null' ;
member2    : STRING ':' value ;

BYTE_ORDER: '"byteOrder"'; IFDS: '"ifds"'; PIXELS: '"pixels"';
BOOL: 'true' | 'false';
INT: [0-9]+;
STRING: '"' (~["\\] | '\\' .)* '"';

(* TiffDiff's wire text IS its JSON serialization (serde camelCase, sparse fields), per
   🦀️component.rs; this documents the real top-level shape, not RFC 8259's own JSON grammar. *)
diff = "{", [ member, { ",", member } ], "}" ;
member = '"byteOrder"', ":", string
       | '"ifds"', ":", ifds triple
       | '"pixels"', ":", "[", { integer }, "]" ;
ifds triple = "{", [ '"removed"', ":", "[", { integer }, "]"
                    , [ ",", '"modified"', ":", "[", { ifd modified }, "]" ]
                    , [ ",", '"added"', ":", "[", { json value }, "]" ] ], "}" ;
ifd modified = "{", '"index"', ":", integer, ",", '"diff"', ":", tags triple, "}" ;
tags triple = "{", [ '"removed"', ":", "[", { integer }, "]"
                    , [ ",", '"modified"', ":", "[", { json value }, "]" ]
                    , [ ",", '"added"', ":", "[", { json value }, "]" ] ], "}" ;
json value = "{", [ member2, { ",", member2 } ], "}"
           | "[", { json value }, "]"
           | string | integer | bool | "null" ;
member2 = string, ":", json value ;
bool = "true" | "false" ;

